51	// Strict base64 decoder: length must be a multiple of four and padding may
52	// only appear at the very end.
53	bool base64_decode(const std::string& input,
54	                   std::vector<unsigned char>& output) {
55	    if (input.size() % 4 != 0) return false;
56	    output.clear();
57	    output.reserve(input.size() / 4 * 3);
58	    for (size_t i = 0; i < input.size(); i += 4) {
59	        bool last_group = (i + 4 == input.size());
60	        int values[4] = {};
61	        int padding = 0;
62	        for (int j = 0; j < 4; ++j) {
63	            char c = input[i + j];
64	            if (c == '=') {
65	                ++padding;
66	            } else {
67	                if (padding > 0) return false;  // data after padding
68	                values[j] = base64_value(c);
69	                if (values[j] < 0) return false;
70	            }
71	        }
72	        if (!last_group && padding > 0) return false;
73	        if (padding > 2) return false;
74	        output.push_back(static_cast<unsigned char>((values[0] << 2) |
75	                                                    (values[1] >> 4)));
76	        if (padding < 2) {
77	            output.push_back(static_cast<unsigned char>(((values[1] & 0x0f) << 4) |
78	                                                        (values[2] >> 2)));
79	        }
80	        if (padding == 0) {
81	            output.push_back(static_cast<unsigned char>(((values[2] & 0x03) << 6) |
82	                                                        values[3]));
83	        }
84	    }
85	    return true;
86	}
