145	bool is_valid_utf8(const std::string& s) {
146	    const auto* p = reinterpret_cast<const unsigned char*>(s.data());
147	    size_t i = 0;
148	    while (i < s.size()) {
149	        unsigned c = p[i];
150	        size_t extra = 0;
151	        unsigned codepoint = 0;
152	        if (c < 0x80) {
153	            ++i;
154	            continue;
155	        }
156	        if ((c & 0xe0) == 0xc0) {
157	            extra = 1;
158	            codepoint = c & 0x1f;
159	        } else if ((c & 0xf0) == 0xe0) {
160	            extra = 2;
161	            codepoint = c & 0x0f;
162	        } else if ((c & 0xf8) == 0xf0) {
163	            extra = 3;
164	            codepoint = c & 0x07;
165	        } else {
166	            return false;
167	        }
168	        if (i + extra >= s.size()) return false;
169	        for (size_t j = 1; j <= extra; ++j) {
170	            if ((p[i + j] & 0xc0) != 0x80) return false;
171	            codepoint = (codepoint << 6) | (p[i + j] & 0x3f);
172	        }
173	        if (codepoint < (extra == 1 ? 0x80u : extra == 2 ? 0x800u : 0x10000u)) {
174	            return false;  // overlong encoding
175	        }
176	        if (codepoint >= 0xd800 && codepoint <= 0xdfff) return false;  // surrogate
177	        if (codepoint > 0x10ffff) return false;
178	        i += extra + 1;
179	    }
180	    return true;
181	}
