183	// Fallback for legacy string types (e.g. T61/IA5 with Latin-1 bytes) that
184	// OpenSSL cannot turn into proper UTF-8 directly.
185	std::string latin1_to_utf8(const std::string& s) {
186	    std::string out;
187	    for (unsigned char c : s) {
188	        if (c < 0x80) {
189	            out.push_back(static_cast<char>(c));
190	        } else {
191	            out.push_back(static_cast<char>(0xc0 | (c >> 6)));
192	            out.push_back(static_cast<char>(0x80 | (c & 0x3f)));
193	        }
194	    }
195	    return out;
196	}
