278	bool format_time(const ASN1_TIME* time, std::string& out) {
279	    struct tm tm_value {};
280	    if (ASN1_TIME_to_tm(time, &tm_value) != 1) return false;
281	    char buffer[32];
282	    int written = std::snprintf(
283	        buffer, sizeof(buffer), "%04d-%02d-%02dT%02d:%02d:%02dZ",
284	        tm_value.tm_year + 1900, tm_value.tm_mon + 1, tm_value.tm_mday,
285	        tm_value.tm_hour, tm_value.tm_min, tm_value.tm_sec);
286	    if (written <= 0 || static_cast<size_t>(written) >= sizeof(buffer)) {
287	        return false;
288	    }
289	    out.assign(buffer);
290	    return true;
291	}
