293	std::string format_fingerprint(const unsigned char* digest, size_t length) {
294	    std::string out;
295	    out.reserve(length * 3);
296	    for (size_t i = 0; i < length; ++i) {
297	        char byte_buffer[4];
298	        std::snprintf(byte_buffer, sizeof(byte_buffer), "%02X", digest[i]);
299	        if (i != 0) out.push_back(':');
300	        out.append(byte_buffer);
301	    }
302	    return out;
303	}
