305	// Describes why a non-regular file type cannot serve as certificate input.
306	// Every message states that the target is not a regular file so the reader
307	// can tell "pick another path" apart from "the certificate content is bad".
308	const char* non_regular_file_reason(mode_t mode) {
309	    if (S_ISDIR(mode)) {
310	        return "is a directory, not a regular file";
311	    }
312	    if (S_ISCHR(mode)) {
313	        return "is a character device, not a regular file";
314	    }
315	    if (S_ISBLK(mode)) {
316	        return "is a block device, not a regular file";
317	    }
318	    if (S_ISFIFO(mode)) {
319	        return "is a named pipe (FIFO), not a regular file";
320	    }
321	    if (S_ISSOCK(mode)) {
322	        return "is a socket, not a regular file";
323	    }
324	    return "is not a regular file";
325	}
