327	// Reads the whole regular file into contents. Only a complete read that
328	// reaches end of file is a success: a non-regular file type (directory,
329	// named pipe, character/block device or socket), a partial read followed by
330	// an error, or any stat/open failure all return a read error message.
331	//
332	// The type check happens via stat() BEFORE open(): opening a FIFO blocks
333	// until another process opens it for writing (the rejection must not depend
334	// on any writer existing), and a device such as /dev/null returns immediate
335	// EOF that would otherwise be misread as an empty certificate. stat()
336	// follows symlinks, so a link is accepted or rejected based on its final
337	// target while the diagnostic still names the link path the user passed.
338	// errno is captured immediately after the failing call so the reason always
339	// belongs to this operation (never a stale "Success").
340	bool read_file_contents(const std::string& path, std::string& contents,
341	                        std::string& error) {
342	    struct stat status {};
343	    if (stat(path.c_str(), &status) != 0) {
344	        // Covers a missing path, a dangling symlink target, and denied
345	        // search permission on a path component.
346	        int saved_errno = errno;
347	        error = std::strerror(saved_errno);
348	        return false;
349	    }
350	    if (!S_ISREG(status.st_mode)) {
351	        // Reject without ever opening the path: no blocking on a FIFO, no
352	        // reading from a device or socket.
353	        error = std::string(non_regular_file_reason(status.st_mode)) +
354	                "; inspect only accepts a regular file as a certificate "
355	                "file";
356	        return false;
357	    }
358	
359	    // O_NONBLOCK makes open() return immediately even if the path was
360	    // swapped for a FIFO between the stat() above and this open(); on
361	    // regular files the flag has no effect on Linux, so the read loop below
362	    // behaves exactly as before.
363	    int fd = open(path.c_str(), O_RDONLY | O_NONBLOCK);
364	    if (fd < 0) {
365	        int saved_errno = errno;
366	        error = std::strerror(saved_errno);
367	        return false;
368	    }
369	
370	    struct stat fd_status {};
371	    if (fstat(fd, &fd_status) != 0) {
372	        int saved_errno = errno;
373	        close(fd);
374	        error = std::strerror(saved_errno);
375	        return false;
376	    }
377	    // The path could have been swapped between stat() and open(); the opened
378	    // descriptor is what gets read, so its type must win.
379	    if (!S_ISREG(fd_status.st_mode)) {
380	        close(fd);
381	        error = std::string(non_regular_file_reason(fd_status.st_mode)) +
382	                "; inspect only accepts a regular file as a certificate "
383	                "file";
384	        return false;
385	    }
386	
387	    contents.clear();
388	    if (fd_status.st_size > 0) {
389	        contents.reserve(static_cast<size_t>(fd_status.st_size));
390	    }
391	    char buffer[65536];
392	    while (true) {
393	        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
394	        if (bytes_read > 0) {
395	            contents.append(buffer, static_cast<size_t>(bytes_read));
396	        } else if (bytes_read == 0) {
397	            break;  // end of file reached after a complete read
398	        } else if (errno != EINTR) {
399	            int saved_errno = errno;
400	            close(fd);
401	            contents.clear();
402	            error = std::strerror(saved_errno);
403	            return false;
404	        }
405	    }
406	
407	    if (close(fd) != 0) {
408	        int saved_errno = errno;
409	        contents.clear();
410	        error = std::strerror(saved_errno);
411	        return false;
412	    }
413	    return true;
414	}
