416	int inspect_file(const std::string& path) {
417	    std::string content;
418	    std::string read_error;
419	    if (!read_file_contents(path, content, read_error)) {
420	        std::cerr << "trustpeek: failed to read file '" << path
421	                  << "': " << read_error << '\n';
422	        return 1;
423	    }
424	
425	    if (content.empty()) {
426	        std::cerr << "trustpeek: invalid certificate in '" << path
427	                  << "': empty file\n";
428	        return 1;
429	    }
430	
431	    // The encoding is decided by what actually parses, never by the file
432	    // extension and never by marker-like text inside the certificate itself
433	    // (a subject name may legitimately contain "-----BEGIN CERTIFICATE-----").
434	    //
435	    // A DER certificate starts with a SEQUENCE tag (0x30), which no PEM file
436	    // can start with, so the two formats cannot be confused: try DER first
437	    // and require the certificate to occupy the entire file.
438	    const auto* const der_begin =
439	        reinterpret_cast<const unsigned char*>(content.data());
440	    const auto* const der_end = der_begin + content.size();
441	    const unsigned char* pointer = der_begin;
442	
443	    X509Ptr cert(d2i_X509(nullptr, &pointer,
444	                          static_cast<long>(content.size())),
445	                 X509_free);
446	    bool is_pem = false;
447	
448	    if (cert) {
449	        if (pointer != der_end) {
450	            std::cerr << "trustpeek: invalid certificate in '" << path
451	                      << "': trailing bytes after DER certificate\n";
452	            return 1;
453	        }
454	    } else {
455	        BioPtr bio(BIO_new_mem_buf(content.data(),
456	                                  static_cast<int>(content.size())),
457	                   BIO_free_all);
458	        if (!bio) {
459	            std::cerr << "trustpeek: internal error while reading '" << path
460	                      << "'\n";
461	            return 1;
462	        }
463	        cert.reset(PEM_read_bio_X509(bio.get(), nullptr, nullptr, nullptr));
464	        if (!cert) {
465	            // The marker search below only picks the diagnostic wording;
466	            // acceptance is always decided by the parse results above.
467	            if (content.find(kPemBegin) != std::string::npos) {
468	                std::cerr << "trustpeek: invalid certificate in '" << path
469	                          << "': PEM certificate block is malformed or "
470	                             "truncated\n";
471	            } else {
472	                std::cerr << "trustpeek: invalid certificate in '" << path
473	                          << "': DER certificate is malformed or truncated\n";
474	            }
475	            return 1;
476	        }
477	        is_pem = true;
478	    }
479	
480	    std::vector<unsigned char> der;
481	    if (!encode_to_der(cert.get(), der)) {
482	        std::cerr << "trustpeek: invalid certificate in '" << path
483	                  << "': failed to re-encode certificate\n";
484	        return 1;
485	    }
486	
487	    if (is_pem && !validate_single_pem(content, der)) {
488	        std::cerr << "trustpeek: invalid certificate in '" << path
489	                  << "': expected exactly one PEM certificate block with no "
490	                     "other non-whitespace content\n";
491	        return 1;
492	    }
493	
494	    const char* encoding_name = is_pem ? "PEM" : "DER";
495	
496	    std::string subject;
497	    std::string issuer;
498	    std::string not_before;
499	    std::string not_after;
500	    if (!format_name(X509_get_subject_name(cert.get()), subject) ||
501	        !format_name(X509_get_issuer_name(cert.get()), issuer) ||
502	        !format_time(X509_get0_notBefore(cert.get()), not_before) ||
503	        !format_time(X509_get0_notAfter(cert.get()), not_after)) {
504	        std::cerr << "trustpeek: invalid certificate in '" << path
505	                  << "': failed to parse certificate fields\n";
506	        return 1;
507	    }
508	
509	    unsigned char digest[EVP_MAX_MD_SIZE];
510	    size_t digest_length = 0;
511	    if (EVP_Q_digest(nullptr, "SHA256", nullptr, der.data(), der.size(), digest,
512	                     &digest_length) != 1) {
513	        std::cerr << "trustpeek: internal error while hashing '" << path
514	                  << "'\n";
515	        return 1;
516	    }
517	
518	    std::ostringstream output;
519	    output << "Encoding: " << encoding_name << '\n'
520	           << "Subject: " << subject << '\n'
521	           << "Issuer: " << issuer << '\n'
522	           << "Not Before: " << not_before << '\n'
523	           << "Not After: " << not_after << '\n'
524	           << "SHA-256 Fingerprint: "
525	           << format_fingerprint(digest, digest_length) << '\n'
526	           << "Note: this output displays certificate information only; "
527	              "reading the file successfully does not verify the signature "
528	              "or establish trust.\n";
529	    std::cout << output.str();
530	    return 0;
531	}
532	
533	}  // namespace
534	
535	int main(int argc, char* argv[]) {
536	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
537	        std::cout << "trustpeek 0.1.0\n";
538	        return 0;
539	    }
540	    if (argc == 3 && std::string_view(argv[1]) == "inspect") {
541	        return inspect_file(argv[2]);
542	    }
543	    print_usage();
544	    return 2;
545	}
